// Schéma dynamique de l'Onduleur : le régime (triphasé/monophasé) de chaque réseau est choisi
// par l'utilisateur et stocké dans eq.controles.regimes_reseaux — le schéma (et donc les champs
// affichés) se recalcule en fonction de ce choix, section par section.
function getOnduleurRegimes(eq) {
  const r = (eq.controles && eq.controles.regimes_reseaux) || {};
  return {
    normalMono: r.normal === "Monophasé",
    secoursMono: r.secours === "Monophasé",
    utilisationMono: r.utilisation === "Monophasé",
    onduleurMono: r.onduleur === "Monophasé",
  };
}
function getSchema(eq) {
  if (eq.type === "Onduleur") {
    const schema = buildOnduleurSchema(getOnduleurRegimes(eq));
    // Un onduleur sécurité n'a ni réseau secours, ni by-pass / commutation R2 (RS) — masqués.
    if (eq.identification?.typeUPS === "Onduleur sécurité") {
      const ITEMS_R2_A_MASQUER = ["auto_alim_commutateur", "commutation_r0_r2", "controle_rs"];
      const sections = schema.sections
        .filter((s) => s.key !== "mesures_reseau_secours" && s.key !== "bypass_synoptique")
        .map((s) => (s.key === "etat_onduleur" ? { ...s, items: s.items.filter((it) => !ITEMS_R2_A_MASQUER.includes(it.key)) } : s));
      return { ...schema, sections };
    }
    return schema;
  }
  if (eq.type === "Redresseur chargeur") return buildRedresseurSchema({ reseauMono: getOnduleurRegimes(eq).normalMono });
  if (eq.type === "Inverseur de source") {
    const r = (eq.controles && eq.controles.regimes_reseaux) || {};
    return buildInverseurSchema({ source1Mono: r.source1 === "Monophasé", source2Mono: r.source2 === "Monophasé", utilisationMono: r.utilisation === "Monophasé" });
  }
  if (eq.type === "Transformateur") return buildTransformateurSchema({ sec: eq.identification?.typeIsolation === "Sec (résine/enrobé)", classeIsolation: eq.identification?.classeIsolation });
  if (eq.type === "Interrupteur HTA") return buildInterrupteurHTASchema({ avecRelais: eq.identification?.presenceRelais === "Oui" });
  if (eq.type === "Interrupteur Fusible HTA") return buildInterrupteurFusibleHTASchema({ avecRelais: eq.identification?.presenceRelais === "Oui" });
  return SCHEMAS[eq.type];
}
// Classement d'un contrôle selon les niveaux de maintenance AFNOR (NF X60-000), par règle générique
// selon la nature du geste plutôt qu'un étiquetage manuel item par item :
// - "1-2" (exploitant, sans instrument) : contrôle purement visuel (état/action), sans aucune
//   valeur mesurée ni interprétation calculée à partir d'une mesure.
// - "3-4" (technicien spécialisé HT Maintenance) : dès qu'un champ porte une unité (valeur
//   mesurée) ou une interprétation calculée (longText, ex. analyse d'huile, DAR/PI) — nécessite un
//   instrument de mesure, un démontage ou une analyse.
function niveauItem(item) {
  const champs = item.fields || [];
  const aUneMesure = champs.some((f) => !!f.unit || (f.compute && f.longText));
  return aUneMesure ? "3-4" : "1-2";
}
const NIVEAUX_MAINTENANCE = ["1-2", "3-4", "1-4"];
const LABEL_NIVEAU_MAINTENANCE = { "1-2": "Niveau 1-2 — Exploitant (visuel)", "3-4": "Niveau 3-4 — Technicien spécialisé (mesures)", "1-4": "Niveau 1-4 — Gamme complète" };
// Filtre les sections/items d'un schéma selon le niveau de maintenance choisi pour l'équipement —
// "1-4" ne filtre rien (comportement historique inchangé). Les sections qui n'ont plus aucun item
// après filtrage sont retirées, pour ne pas afficher un titre de section vide.
function schemaFiltreeParNiveau(schema, niveauMaintenance) {
  if (!schema || !niveauMaintenance || niveauMaintenance === "1-4") return schema;
  const sections = schema.sections
    .map((sec) => ({ ...sec, items: sec.items.filter((it) => niveauItem(it) === niveauMaintenance) }))
    .filter((sec) => sec.items.length > 0);
  return { ...schema, sections };
}

