// Accord grammatical (masculin/féminin, singulier/pluriel) des mots d'état ("Dégradé(e)(s)", "Défaillant(e)(s)"…)
function agree(word, gender, plural) {
  let w = word;
  if (gender === "f" && !w.endsWith("e")) w += "e";
  if (plural && !w.endsWith("s")) w += "s";
  return w;
}
