// Filet de sécurité / migration : les interventions créées avant l'introduction du support
// multi-équipements n'avaient qu'un seul objet "equipement" — on le convertit en liste à la volée,
// sans jamais perdre les données existantes.
function repairIntervention(iv) {
  if (!iv.equipements) {
    const ancien = iv.equipement;
    const nonVide = ancien && (ancien.type || ancien.constructeur || ancien.modele || ancien.numeroSerie || ancien.localisation || ancien.reference);
    iv.equipements = nonVide ? [{ id: uid(), ...ancien }] : [];
  }
  if (!iv.offre) iv.offre = { numero: "", fichier: [] };
  return iv;
}

function dureeIntervention(heureDebut, heureFin) {
  if (!heureDebut || !heureFin) return "";
  const [h1, m1] = heureDebut.split(":").map(Number);
  const [h2, m2] = heureFin.split(":").map(Number);
  let mins = (h2 * 60 + m2) - (h1 * 60 + m1);
  if (isNaN(mins)) return "";
  if (mins < 0) mins += 24 * 60;
  const h = Math.floor(mins / 60), m = mins % 60;
  return `${h}h${String(m).padStart(2, "0")}`;
}

function prefillInterventionFromSite(site, eqOrList, numeroRI) {
  const base = emptyIntervention(numeroRI);
  const list = Array.isArray(eqOrList) ? eqOrList : (eqOrList ? [eqOrList] : []);
  const equipements = list.map((eq) => {
    const idf = eq.identification || {};
    return {
      id: uid(),
      type: eq.type || "",
      constructeur: idf.marque || (site.locaux || []).find((l) => l.id === eq.localId)?.marque || "",
      modele: idf.modele || idf.typeCellule || idf.typeTransformateur || idf.typeDisjoncteur || "",
      numeroSerie: idf.numeroSerie || idf.numeroSerieDisjoncteur || idf.numeroSerieContacteur || idf.numeroSerieRelais || "",
      localisation: (site.locaux || []).find((l) => l.id === eq.localId)?.nom || site.local || "",
      reference: idf.repere || "",
      etat: eq.etatFinal || "Conforme",
      remarque: eq.remarques || "",
    };
  });
  return {
    ...base,
    client: site.client,
    site: site.nom || site.local,
    emailClient: site.emailEnvoi || "",
    date: site.rapport.date || todayISO(),
    technicien: site.rapport.intervenant || "",
    heureDebut: site.rapport.heureArrivee || "",
    heureFin: site.rapport.heureFin || "",
    equipements,
    nature: { ...base.nature, preventive: true },
    conclusion: list.length === 1 ? list[0].etatFinal : rankToLabel(overallRank(site)),
    anomaliesRecommandations: list.length === 1 ? (list[0].remarques || "") : "",
    linkedSiteId: site.id,
    linkedEquipementId: list.length === 1 ? list[0].id : null,
    offre: { ...base.offre, numero: site.rapport?.offre?.numero || "" },
  };
}

// Repère les champs importants manquants avant de générer un rapport Word — simple avertissement,
// non bloquant : l'utilisateur choisit de continuer ou de compléter d'abord.
function siteExportWarnings(site) {
  const w = [];
  if (!site.nom) w.push("Le nom du site n'est pas renseigné");
  if (!site.client) w.push("La dénomination client n'est pas renseignée");
  if (!site.rapport.date) w.push("La date d'intervention n'est pas renseignée");
  if (!site.rapport.intervenant) w.push("L'intervenant principal n'est pas renseigné");
  if (site.equipements.length === 0) w.push("Aucun équipement n'a été ajouté sur ce site");
  site.equipements.forEach((eq) => {
    const nomEq = `${eq.type}${eq.identification.repere ? " — " + eq.identification.repere : ""}`;
    if (eq.etatFinal !== "Conforme") return; // déjà signalé comme non conforme, pas besoin d'alerte supplémentaire
    if (gradinsHorsTolerance(eq)) w.push(`${nomEq} : un courant de gradin est hors tolérance mais l'état final est toujours « Conforme »`);
    if (elementsBatterieHorsTolerance(eq)) w.push(`${nomEq} : un élément de batterie est hors tolérance mais l'état final est toujours « Conforme »`);
    if (valeursHorsToleranceGenerique(eq)) w.push(`${nomEq} : une mesure dépasse la tolérance indiquée (résistance de contact, bobine, continuité...) mais l'état final est toujours « Conforme »`);
    if (tempsManoeuvreHorsTolerance(eq)) w.push(`${nomEq} : un temps de manœuvre s'écarte significativement de la référence constructeur mais l'état final est toujours « Conforme »`);
    if (rapportTransformationHorsTolerance(eq)) w.push(`${nomEq} : le rapport de transformation mesuré sort de la tolérance CEI 60076-1 mais l'état final est toujours « Conforme »`);
  });
  return w;
}
function ivExportWarnings(iv) {
  const w = [];
  if (!iv.client) w.push("Le client n'est pas renseigné");
  if (!iv.site) w.push("Le site n'est pas renseigné");
  if (!iv.date) w.push("La date d'intervention n'est pas renseignée");
  if (!iv.technicien) w.push("Le technicien principal n'est pas renseigné");
  if (!iv.validation.signatureClient && !iv.validation.signatureHT) w.push("Aucune signature (client ou technicien) n'a été enregistrée");
  return w;
}
function overallRank(site) {
  return worstRank([site.rapport.environnementEtat, site.rapport.fonctionnementEtat, ...site.equipements.map((e) => e.etatFinal)]);
}
function rankToLabel(rank) { return rank === 2 ? "Défaillant" : rank === 1 ? "Dégradé" : "Conforme"; }

