  if (!transfo) return { manque: `aucun transformateur avec le repère « ${repereTransfo} » trouvé sur ce site — vérifiez l'orthographe ou qu'il a bien été ajouté` };
  const sn = numOf(transfo.identification?.puissance); // kVA
