    line(20, yTop, 230, yTop); line(20, yBot, 230, yBot);
    line(230, yTop, 230, yEntreeHaut); line(230, yBot, 230, yEntreeBas);
    const depthCS = boxDepth(csW, csH);
    ctx.fillText("Commutateur", csX + csW + 46, yMid - 8);
