async function generateSiteDocx(site, allSites) {
  await ensureDocx();
  bookmarkIdCounter = 0; // repart de zéro à chaque génération, pour des ID propres et prévisibles
  site = await resolvePhotosForDocx(site);
  const rank = overallRank(site);
  const rankLabel = rankToLabel(rank);
  const logoImg = docxImage(LOGO_DARK, 46, 35);
  const headerTable = new DOCX.Table({ width: { size: 8800, type: DOCX.WidthType.DXA }, columnWidths: [8800], rows: [new DOCX.TableRow({ children: [new DOCX.TableCell({
    width: { size: 8800, type: DOCX.WidthType.DXA }, shading: { type: DOCX.ShadingType.CLEAR, fill: DOCX_DARK },
    children: [
      new DOCX.Paragraph({ spacing: { before: 160, after: 20 }, children: [...(logoImg ? [logoImg] : []), new DOCX.TextRun({ text: "   RAPPORT DE MAINTENANCE PRÉVENTIVE HT / BT / CONVERSION D'ÉNERGIE — " + rankLabel.toUpperCase(), color: DOCX_SILVER, size: 16 })] }),
      new DOCX.Paragraph({ spacing: { after: 10 }, children: [new DOCX.TextRun({ text: site.nom || "Site", bold: true, color: DOCX_WHITE, size: 30 })] }),
      new DOCX.Paragraph({ spacing: { after: 160 }, children: [new DOCX.TextRun({ text: [site.client, site.local].filter(Boolean).join(" — "), color: DOCX_SILVER, size: 20 })] }),
    ],
  })] })] });

  const syntheseTable = docxSyntheseTable(site);

  const tousIntervenants = [site.rapport.intervenant, ...(site.rapport.intervenantsSupplementaires || [])].filter(Boolean).join(", ");
  const toutesJournees = [
    { date: site.rapport.date, heureArrivee: site.rapport.heureArrivee, heureFin: site.rapport.heureFin },
    ...(site.rapport.journeesSupplementaires || []),
  ].filter((j) => j.date);
  const journeesTexte = toutesJournees.map((j) => `${j.date}${j.heureArrivee || j.heureFin ? ` (${j.heureArrivee || "?"} – ${j.heureFin || "?"})` : ""}`).join(" · ");
  const formatContact = (c) => c ? [
    [c.prenom, c.nom].filter(Boolean).join(" "),
    c.email,
    c.portable && `Portable : ${c.portable}`,
    c.fixe && `Fixe : ${c.fixe}`,
  ].filter(Boolean).join(" · ") : "";
  const contactSiteTexte = formatContact(site.contactSite);
  // Le contact client n'est affiché que s'il diffère du contact site — évite de répéter la même
  // personne deux fois quand c'est le même interlocuteur pour les deux rôles.
  const memePersonne = site.contactClient && site.contactSite &&
    (site.contactClient.email || "").trim().toLowerCase() === (site.contactSite.email || "").trim().toLowerCase() &&
    (site.contactClient.nom || "").trim().toLowerCase() === (site.contactSite.nom || "").trim().toLowerCase() &&
    (site.contactClient.email || site.contactClient.nom); // ne compte pas deux fiches vides comme "identiques"
  const contactClientTexte = memePersonne ? "" : formatContact(site.contactClient);
  const rapportRows = [
    ...(site.adresse ? [["Adresse du site", site.adresse]] : []),
    ...(contactClientTexte ? [["Contact client", contactClientTexte]] : []),
    ...(contactSiteTexte ? [["Contact site", contactSiteTexte]] : []),
    ["Date(s) d'intervention", journeesTexte || site.rapport.date],
    ["Intervenant(s)", tousIntervenants],
    ["Nombre d'équipements", String(site.equipements.length)], ["Prochaine maintenance recommandée avant", site.rapport.prochaineMaintenance],
    ["Environnement", [site.rapport.environnementEtat, site.rapport.environnementRemarque].filter(Boolean).join(" — ")],
    ["Fonctionnement de l'installation", [site.rapport.fonctionnementEtat, site.rapport.fonctionnementRemarque].filter(Boolean).join(" — ")],
  ];
  const locauxRows = (site.locaux || []).map((l) => ({
    nom: l.nom || "Local sans nom",
    resume: [l.typeDePoste && `Type de poste : ${l.typeDePoste}`, l.regimeNeutre && `Régime de neutre : ${l.regimeNeutre}`, l.marque && `Marque : ${l.marque}`, l.anneeMiseEnService && `Mise en service : ${l.anneeMiseEnService}`].filter(Boolean).join(" · "),
    definition: l.regimeNeutre ? REGIME_NEUTRE_DESCRIPTIONS[l.regimeNeutre] : null,
  }));
  const locauxTable = locauxRows.length && locauxRows.some((l) => l.resume) ? new DOCX.Table({
    width: { size: TABLE_WIDTH, type: DOCX.WidthType.DXA }, columnWidths: [3400, 6200],
    rows: locauxRows.filter((l) => l.resume).map((l) => new DOCX.TableRow({ children: [
      new DOCX.TableCell({ width: { size: 3400, type: DOCX.WidthType.DXA }, margins: CELL_MARGINS, shading: { type: DOCX.ShadingType.CLEAR, fill: DOCX_LIGHT }, children: [new DOCX.Paragraph({ children: [new DOCX.TextRun({ text: l.nom, size: 18, color: "555555" })] })] }),
      new DOCX.TableCell({ width: { size: 6200, type: DOCX.WidthType.DXA }, margins: CELL_MARGINS, children: [
        new DOCX.Paragraph({ spacing: { after: l.definition ? 40 : 0 }, children: [new DOCX.TextRun({ text: l.resume, size: 18, bold: true, color: DOCX_DARK })] }),
        ...(l.definition ? [new DOCX.Paragraph({ children: [new DOCX.TextRun({ text: l.definition, size: 15, italics: true, color: "666666" })] })] : []),
      ]}),
    ]})),
  }) : null;

  const children = [...docxCoverPage(site), headerTable, docxSpacer(160)];
  if (syntheseTable) {
    children.push(docxHeading("Synthèse des équipements"));
    const compteur = { conforme: 0, degrade: 0, defaillant: 0 };
    site.equipements.forEach((eq) => {
      const r = RANK_OF[eq.etatFinal] ?? 0;
      if (r >= 2) compteur.defaillant++; else if (r === 1) compteur.degrade++; else compteur.conforme++;
    });
    const graphSynthese = genererGraphiqueSynthese(compteur);
    if (graphSynthese) {
      const imgSynthese = docxImage(graphSynthese, 300, 160);
      if (imgSynthese) children.push(new DOCX.Paragraph({ spacing: { after: 40 }, children: [imgSynthese] }));
    }
    children.push(syntheseTable); children.push(docxSpacer());
  }
  children.push(docxHeading("Rapport"));
  const rapportTable = docxFieldTable(rapportRows);
  if (rapportTable) children.push(rapportTable);
  if (site.rapport.syntheseRemarques) {
    // Même espacement que celui appliqué avant "Locaux", pour bien détacher cette section de ce
    // qui précède (tableau "Rapport").
    children.push(new DOCX.Paragraph({ spacing: { before: 700, after: 0 }, children: [] }));
    children.push(new DOCX.Paragraph({ spacing: { before: 0, after: 120 }, children: [new DOCX.TextRun({ text: "Synthèse des remarques et préconisations", bold: true, size: 19, color: DOCX_DARK })] }));
    const lignesRemarques = site.rapport.syntheseRemarques.split("\n").filter((l) => l.trim());
    const margeRemarque = { top: 130, bottom: 130, left: 130, right: 120 };
    const remarquesTable = new DOCX.Table({
      width: { size: TABLE_WIDTH, type: DOCX.WidthType.DXA }, columnWidths: [2600, 7000],
      rows: [
        new DOCX.TableRow({ tableHeader: true, children: [
          new DOCX.TableCell({ width: { size: 2600, type: DOCX.WidthType.DXA }, margins: margeRemarque, shading: { type: DOCX.ShadingType.CLEAR, fill: DOCX_LIGHT }, children: [new DOCX.Paragraph({ children: [new DOCX.TextRun({ text: "Équipement", bold: true, size: 17, color: "555555" })] })] }),
          new DOCX.TableCell({ width: { size: 7000, type: DOCX.WidthType.DXA }, margins: margeRemarque, shading: { type: DOCX.ShadingType.CLEAR, fill: DOCX_LIGHT }, children: [new DOCX.Paragraph({ children: [new DOCX.TextRun({ text: "Remarque", bold: true, size: 17, color: "555555" })] })] }),
        ]}),
        ...lignesRemarques.map((ligne) => {
          // Chaque ligne compilée est au format "Équipement (repère) : remarque" — on sépare au
          // premier " : " pour la colonne Équipement, le reste va dans Remarque.
          const idx = ligne.indexOf(" : ");
          const equip = idx >= 0 ? ligne.slice(0, idx).trim() : "";
          const remarque = idx >= 0 ? ligne.slice(idx + 3).trim() : ligne.trim();
          return new DOCX.TableRow({ children: [
            new DOCX.TableCell({ width: { size: 2600, type: DOCX.WidthType.DXA }, margins: margeRemarque, children: [new DOCX.Paragraph({ children: [new DOCX.TextRun({ text: equip, size: 17, color: "555555" })] })] }),
            new DOCX.TableCell({ width: { size: 7000, type: DOCX.WidthType.DXA }, margins: margeRemarque, children: [new DOCX.Paragraph({ children: [new DOCX.TextRun({ text: remarque, size: 18 })] })] }),
          ]});
        }),
      ],
    });
    children.push(remarquesTable);
  }
  else children.push(docxSpacer());
  // Photos générales du site (ajoutées depuis l'onglet Rapport) — absentes du rapport principal
  // jusqu'ici, elles n'étaient reprises que dans le document séparé "Annexe photos".
  const photosSiteRapport = (site.rapport && site.rapport.photos) || [];
  if (photosSiteRapport.length) {
    children.push(new DOCX.Paragraph({ spacing: { before: 40, after: 80 }, children: [new DOCX.TextRun({ text: "Photos générales du site", bold: true, size: 18, color: DOCX_DARK })] }));
    photosSiteRapport.forEach((p) => {
      const img = docxImage(p.dataUrl, 260, 195);
      if (!img) return;
      if (p.caption) children.push(new DOCX.Paragraph({ spacing: { before: 40, after: 4 }, children: [new DOCX.TextRun({ text: p.caption, italics: true, size: 15, color: "666666" })] }));
      children.push(new DOCX.Paragraph({ spacing: { after: 60 }, children: [img] }));
    });
  }

  if (locauxTable) {
    // Grand espacement avant Locaux, pour bien le détacher visuellement de ce qui précède.
    children.push(new DOCX.Paragraph({ spacing: { before: 700, after: 0 }, children: [] }));
    children.push(docxHeading("Locaux")); children.push(locauxTable); children.push(docxSpacer());
  }

  equipementsTries(site.equipements).forEach((eq) => { children.push(...docxEquipementElements(eq, site.locaux, allSites)); });

  children.push(docxSpacer(200));
  children.push(new DOCX.Paragraph({ border: { top: { color: DOCX_SILVER, space: 4, style: DOCX.BorderStyle.SINGLE, size: 4 } }, spacing: { before: 100 }, children: [new DOCX.TextRun({ text: "HT Maintenance — Maintenance électrique HTA / BT", size: 14, color: "888888", italics: true })] }));

  const doc = new DOCX.Document({ features: { updateFields: true }, sections: [{ properties: { page: { margin: { top: 500, bottom: 500, left: 600, right: 600 } } }, footers: { default: docxFooterPagination() }, children }] });
  return DOCX.Packer.toBlob(doc);
}

